// All hardcoded expected strings in this file were generated by running the
// same operations against github.com/shopspring/decimal v1.4.0 and match its
// output exactly, except where a comment documents a deliberate divergence
// (the package-wide truncation convention beyond 19 fractional digits).

func TestParityScientificNotation(t *testing.T) {
	t.Run("valid forms", func(t *testing.T) {
		cases := []struct {
			input    string
			expected string
		}{
			{"1e5", "100000"},
			{"1E5", "100000"},
			{"1.23e-4", "0.000123"},
			{"-1.5e3", "-1500"},
			{"0.5e2", "50"},
			{"1.e5", "100000"},
			{"2E+5", "200000"},
			{"1e19", "10000000000000000000"},
		}
		for _, c := range cases {
			t.Run(c.input, func(t *testing.T) {
				d, err := alpacadecimal.NewFromString(c.input)
				require.NoError(t, err)
				require.Equal(t, c.expected, d.String())
				require.True(t, d.Equal(alpacadecimal.RequireFromString(c.expected)))

				require.NotPanics(t, func() {
					r := alpacadecimal.RequireFromString(c.input)
					require.Equal(t, c.expected, r.String())
				})
			})
		}
	})

	t.Run("invalid forms", func(t *testing.T) {
		for _, input := range []string{"1e", "1e5.5", "e5", "1ee5"} {
			t.Run(input, func(t *testing.T) {
				_, err := alpacadecimal.NewFromString(input)
				require.Error(t, err)
				require.Panics(t, func() { alpacadecimal.RequireFromString(input) })
			})
		}
	})

	t.Run("UnmarshalJSON unquoted", func(t *testing.T) {
		var d alpacadecimal.Decimal
		require.NoError(t, json.Unmarshal([]byte(`1.5e3`), &d))
		require.Equal(t, "1500", d.String())
	})

	t.Run("UnmarshalJSON quoted", func(t *testing.T) {
		var d alpacadecimal.Decimal
		require.NoError(t, json.Unmarshal([]byte(`"1.5e3"`), &d))
		require.Equal(t, "1500", d.String())
	})

	t.Run("UnmarshalText", func(t *testing.T) {
		var d alpacadecimal.Decimal
		require.NoError(t, d.UnmarshalText([]byte("1.5e3")))
		require.Equal(t, "1500", d.String())
	})
}

func TestParityNewExponentRange(t *testing.T) {
	t.Run("large positive exponents", func(t *testing.T) {
		require.NotPanics(t, func() {
			require.Equal(t, "50000000000000000000", alpacadecimal.New(5, 19).String())
		})
		require.NotPanics(t, func() {
			s := alpacadecimal.New(1, 300).String()
			require.Len(t, s, 301) // "1" followed by 300 zeros
			require.Equal(t, "1"+strings.Repeat("0", 300), s)
		})
		require.Equal(t, "0", alpacadecimal.New(0, 19).String())
	})

	t.Run("large negative exponents", func(t *testing.T) {
		require.Equal(t, "0.0000000000000000001", alpacadecimal.New(1, -19).String())

		// Truncation convention: digits beyond 19 fractional places are
		// truncated, so New(1, -20) is 0. shopspring v1.4.0 keeps arbitrary
		// precision and returns "0.00000000000000000001" here.
		require.Equal(t, "0", alpacadecimal.New(1, -20).String())
	})

	t.Run("plain", func(t *testing.T) {
		require.Equal(t, "123.456", alpacadecimal.New(123456, -3).String())
	})
}

func TestParityNewFromBigInt(t *testing.T) {
	coef := new(big.Int).Exp(big.NewInt(10), big.NewInt(250), nil) // 10^250

	t.Run("10^250 exp 0", func(t *testing.T) {
		d := alpacadecimal.NewFromBigInt(coef, 0)
		require.Equal(t, coef.String(), d.String())
		require.Len(t, d.String(), 251)
	})

	t.Run("negative 10^250 exp 199", func(t *testing.T) {
		d := alpacadecimal.NewFromBigInt(new(big.Int).Neg(coef), 199)
		expected := new(big.Int).Mul(
			new(big.Int).Neg(coef),
			new(big.Int).Exp(big.NewInt(10), big.NewInt(199), nil),
		)
		require.Equal(t, expected.String(), d.String())
		require.Len(t, d.String(), 451) // sign + 450 digits
	})

	t.Run("10^250 exp 300", func(t *testing.T) {
		d := alpacadecimal.NewFromBigInt(coef, 300)
		expected := new(big.Int).Mul(
			coef,
			new(big.Int).Exp(big.NewInt(10), big.NewInt(300), nil),
		)
		require.Equal(t, expected.String(), d.String())
		require.Len(t, d.String(), 551)
	})

	t.Run("small stays optimized", func(t *testing.T) {
		d := alpacadecimal.NewFromBigInt(big.NewInt(123), -2)
		require.Equal(t, "1.23", d.String())
		require.True(t, d.IsOptimized())
	})
}

func TestParityNewFromFloat(t *testing.T) {
	t.Run("huge floats no panic", func(t *testing.T) {
		for _, f := range []float64{1e300, math.MaxFloat64} {
			require.NotPanics(t, func() {
				d := alpacadecimal.NewFromFloat(f)
				require.Equal(t, strconv.FormatFloat(f, 'f', -1, 64), d.String())
			})
		}
	})

	t.Run("NaN and Inf panic", func(t *testing.T) {
		require.Panics(t, func() { alpacadecimal.NewFromFloat(math.NaN()) })
		require.Panics(t, func() { alpacadecimal.NewFromFloat(math.Inf(1)) })
		require.Panics(t, func() { alpacadecimal.NewFromFloat(math.Inf(-1)) })
	})

	t.Run("fast path identity", func(t *testing.T) {
		// expected strings are shopspring v1.4.0 outputs, equal to
		// strconv.FormatFloat(f, 'f', -1, 64).
		cases := []struct {
			input    float64
			expected string
		}{
			{1.23, "1.23"},
			{0.1, "0.1"},
			{2.675, "2.675"},
			{8191.999999999999, "8191.999999999999"},
			{0.000000000001, "0.000000000001"},
			{-55.55, "-55.55"},
		}
		for _, c := range cases {
			t.Run(c.expected, func(t *testing.T) {
				require.Equal(t, c.expected, alpacadecimal.NewFromFloat(c.input).String())
			})
		}
	})
}

func TestParityNewFromFloatWithExponent(t *testing.T) {
	// Rounds half away from zero; expected strings match shopspring v1.4.0.
	cases := []struct {
		input    float64
		exp      int32
		expected string
	}{
		{123.456, -2, "123.46"},
		{123.454, -2, "123.45"},
		{-123.456, -2, "-123.46"},
		{12345.0, 2, "12300"},
	}
	for _, c := range cases {
		t.Run(c.expected, func(t *testing.T) {
			require.Equal(t, c.expected, alpacadecimal.NewFromFloatWithExponent(c.input, c.exp).String())
		})
	}
}

