func TestParityBinaryGob(t *testing.T) {
	values := []string{"123.45", "-0.001", "0", "123456789.123456789", "9223372", "1.5", "0.000000000000000001"}

	// shopspring's binary format is a 4-byte big-endian exponent followed by
	// the gob encoding of the big.Int coefficient; the helpers below
	// reproduce it with the standard library only, so the main module does
	// not need shopspring as a dependency.

	t.Run("alpacadecimal to shopspring format", func(t *testing.T) {
		for _, v := range values {
			t.Run(v, func(t *testing.T) {
				data, err := alpacadecimal.RequireFromString(v).MarshalBinary()
				require.NoError(t, err)
				require.Equal(t, v, shopspringFormatDecode(t, data))
			})
		}
	})

	t.Run("shopspring format to alpacadecimal", func(t *testing.T) {
		for _, v := range values {
			t.Run(v, func(t *testing.T) {
				data := shopspringFormatEncode(t, v)

				var ad alpacadecimal.Decimal
				require.NoError(t, ad.UnmarshalBinary(data))
				require.Equal(t, v, ad.String())
			})
		}
	})

	t.Run("gob struct round-trip", func(t *testing.T) {
		type wrapper struct {
			D  alpacadecimal.Decimal
			ND alpacadecimal.NullDecimal
		}

		for _, v := range values {
			t.Run(v, func(t *testing.T) {
				in := wrapper{
					D:  alpacadecimal.RequireFromString(v),
					ND: alpacadecimal.NewNullDecimal(alpacadecimal.RequireFromString(v).Neg()),
				}

				var buf bytes.Buffer
				require.NoError(t, gob.NewEncoder(&buf).Encode(in))

				var out wrapper
				require.NoError(t, gob.NewDecoder(&buf).Decode(&out))
				require.Equal(t, in.D.String(), out.D.String())
				require.True(t, out.ND.Valid)
				require.Equal(t, in.ND.Decimal.String(), out.ND.Decimal.String())
			})
		}
	})
}

// shopspringFormatEncode builds the exact bytes shopspring's MarshalBinary
// produces for a plain decimal string: big-endian int32 exponent, then the
// big.Int gob encoding of the coefficient.
func shopspringFormatEncode(t *testing.T, value string) []byte {
	t.Helper()
	exp := 0
	digits := value
	if dot := strings.IndexByte(value, '.'); dot >= 0 {
		exp = -(len(value) - dot - 1)
		digits = value[:dot] + value[dot+1:]
	}
	coef, ok := new(big.Int).SetString(digits, 10)
	require.True(t, ok)
	gobBytes, err := coef.GobEncode()
	require.NoError(t, err)
	out := make([]byte, 4, 4+len(gobBytes))
	binary.BigEndian.PutUint32(out, uint32(int32(exp)))
	return append(out, gobBytes...)
}

// shopspringFormatDecode decodes shopspring-format bytes (as shopspring's
// UnmarshalBinary would) and renders the value as a trimmed decimal string.
func shopspringFormatDecode(t *testing.T, data []byte) string {
	t.Helper()
	require.GreaterOrEqual(t, len(data), 4)
	exp := int32(binary.BigEndian.Uint32(data[:4]))
	coef := new(big.Int)
	require.NoError(t, coef.GobDecode(data[4:]))

	neg := coef.Sign() < 0
	abs := new(big.Int).Abs(coef).String()
	var s string
	switch {
	case exp >= 0:
		s = abs + strings.Repeat("0", int(exp))
	default:
		frac := int(-exp)
		if frac >= len(abs) {
			abs = strings.Repeat("0", frac-len(abs)+1) + abs
		}
		s = abs[:len(abs)-frac] + "." + abs[len(abs)-frac:]
		s = strings.TrimRight(s, "0")
		s = strings.TrimRight(s, ".")
	}
	if s == "" {
		s = "0"
	}
	if neg && s != "0" {
		s = "-" + s
	}
	return s
}

func TestParityJSONNullAndScan(t *testing.T) {
	t.Run("UnmarshalJSON null is a no-op", func(t *testing.T) {
		d := alpacadecimal.NewFromInt(5)
		require.NoError(t, d.UnmarshalJSON([]byte("null")))
		require.Equal(t, "5", d.String())
	})

	t.Run("Scan float32", func(t *testing.T) {
		var d alpacadecimal.Decimal
		require.NoError(t, d.Scan(float32(123.456)))
		require.True(t, d.Equal(alpacadecimal.NewFromFloat(float64(float32(123.456)))))
		require.Equal(t, "123.45600128173828", d.String()) // matches shopspring v1.4.0
	})

	t.Run("Scan int errors", func(t *testing.T) {
		var d alpacadecimal.Decimal
		require.Error(t, d.Scan(int(5))) // like shopspring, plain int is not supported
	})

	t.Run("Scan uint64", func(t *testing.T) {
		var d alpacadecimal.Decimal
		require.NoError(t, d.Scan(uint64(5)))
		require.Equal(t, "5", d.String())
	})

	t.Run("Scan quoted string", func(t *testing.T) {
		var d alpacadecimal.Decimal
		require.NoError(t, d.Scan("\"1.5\"")) // shopspring unquotes in Scan
		require.Equal(t, "1.5", d.String())
	})

	t.Run("NullDecimal Scan nil", func(t *testing.T) {
		var nd alpacadecimal.NullDecimal
		require.NoError(t, nd.Scan(nil))
		require.False(t, nd.Valid)
	})
}

func TestParityFloat64Exactness(t *testing.T) {
	cases := []struct {
		value string
		f     float64
		exact bool
	}{
		{"0.5", 0.5, true},
		{"0.1", 0.1, false},
		{"1", 1, true},
		{"0.3", 0.3, false},
	}
	for _, c := range cases {
		t.Run(c.value, func(t *testing.T) {
			f, exact := alpacadecimal.RequireFromString(c.value).Float64()
			require.Equal(t, c.f, f)
			require.Equal(t, c.exact, exact)
		})
	}

	t.Run("InexactFloat64", func(t *testing.T) {
		require.Equal(t, 0.1, alpacadecimal.RequireFromString("0.1").InexactFloat64())
	})
}

func TestParityIntPart(t *testing.T) {
	t.Run("huge fallback no panic", func(t *testing.T) {
		huge := alpacadecimal.NewFromBigInt(new(big.Int).Exp(big.NewInt(10), big.NewInt(250), nil), 0)
		require.NotPanics(t, func() { huge.IntPart() })
	})

	t.Run("just out of fixed range", func(t *testing.T) {
		d := alpacadecimal.RequireFromString("-9223372.036854775808")
		require.False(t, d.IsOptimized())
		require.Equal(t, int64(-9223372), d.IntPart())
	})
}

func TestParityRepresentationInvariance(t *testing.T) {
	t.Run("Sub shrinks back to fixed", func(t *testing.T) {
		big := alpacadecimal.RequireFromString("9223373")
		require.False(t, big.IsOptimized())

		d := big.Sub(alpacadecimal.NewFromInt(2))
		require.Equal(t, "9223371", d.String())
		require.True(t, d.IsOptimized())
	})

	t.Run("Mod of fallback fits", func(t *testing.T) {
		d := alpacadecimal.RequireFromString("9223373.5")
		require.False(t, d.IsOptimized())

		m := d.Mod(alpacadecimal.NewFromInt(2))
		require.Equal(t, "1.5", m.String())
		require.True(t, m.IsOptimized())
	})

	t.Run("Truncate of fallback fits", func(t *testing.T) {
		d := alpacadecimal.RequireFromString("9223372.9")
		require.False(t, d.IsOptimized())

		tr := d.Truncate(0)
		require.Equal(t, "9223372", tr.String())
		require.True(t, tr.IsOptimized())
	})

	t.Run("Round of fallback fits", func(t *testing.T) {
		d := alpacadecimal.RequireFromString("9223372.4")
		require.False(t, d.IsOptimized())

		r := d.Round(0)
		require.Equal(t, "9223372", r.String())
		require.True(t, r.IsOptimized())
	})
}
